import zipfile
import re
import xml.etree.ElementTree as ET

NS = {
    'm': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
    'r': 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
}

path = "budget.xlsx"
z = zipfile.ZipFile(path)
names = z.namelist()
print("Archive entries:")
for n in names:
    print(" ", n)

wb_xml = z.read('xl/workbook.xml').decode('utf-8')
root = ET.fromstring(wb_xml)
sheets = [(s.get('name'), s.get('sheetId'), s.get('{http://schemas.openxmlformats.org/officeDocument/2006/relationships}id'))
          for s in root.find('m:sheets', NS)]
print("\nSheets:", sheets)

rels_xml = z.read('xl/_rels/workbook.xml.rels').decode('utf-8')
rels_root = ET.fromstring(rels_xml)
rel_map = {r.get('Id'): r.get('Target') for r in rels_root}

# shared strings
shared = []
if 'xl/sharedStrings.xml' in names:
    ss_root = ET.fromstring(z.read('xl/sharedStrings.xml').decode('utf-8'))
    for si in ss_root.findall('m:si', NS):
        texts = [t.text or '' for t in si.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t')]
        shared.append(''.join(texts))

def col_to_idx(ref):
    m = re.match(r'([A-Z]+)(\d+)', ref)
    col_str = m.group(1)
    col = 0
    for ch in col_str:
        col = col * 26 + (ord(ch) - 64)
    return col - 1, int(m.group(2))

for i, (name, sheet_id, rid) in enumerate(sheets):
    target = rel_map.get(rid)
    if not target.startswith('xl/'):
        target = 'xl/' + target.lstrip('/')
    xml_path = target
    print(f"\n=== Sheet {name!r} -> {xml_path} ===")
    ws_root = ET.fromstring(z.read(xml_path).decode('utf-8'))
    rows = {}
    for c in ws_root.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}c'):
        ref = c.get('r')
        t = c.get('t')
        v = c.find('m:v', NS)
        val = None
        if v is not None:
            if t == 's':
                val = shared[int(v.text)]
            elif t == 'inlineStr':
                is_elem = c.find('m:is', NS)
                val = ''.join(x.text or '' for x in is_elem.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
            elif t == 'b':
                val = v.text == '1'
            else:
                val = v.text
        elif t == 'inlineStr':
            is_elem = c.find('m:is', NS)
            val = ''.join(x.text or '' for x in is_elem.iter('{http://schemas.openxmlformats.org/spreadsheetml/2006/main}t'))
        if val is not None:
            col, row = col_to_idx(ref)
            rows.setdefault(row, {})[col] = val
    max_row = max(rows) if rows else 0
    for r in range(1, max_row + 1):
        cells = rows.get(r, {})
        line = ' | '.join(f"{cells.get(c)}" for c in sorted(cells))
        print(f"R{r}: {line}")

