import zipfile
import re
import xml.etree.ElementTree as ET
from collections import OrderedDict

NS = {'m': 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'}
TAG = '{http://schemas.openxmlformats.org/spreadsheetml/2006/main}'

z = zipfile.ZipFile("budget.xlsx")

shared = []
if 'xl/sharedStrings.xml' in z.namelist():
    ss_root = ET.fromstring(z.read('xl/sharedStrings.xml').decode('utf-8'))
    for si in ss_root.findall('m:si', NS):
        shared.append(''.join(t.text or '' for t in si.iter(TAG + 't')))

ws_root = ET.fromstring(z.read('xl/worksheets/sheet1.xml').decode('utf-8'))

rows = {}
for c in ws_root.iter(TAG + 'c'):
    ref = c.get('r')
    m = re.match(r'([A-Z]+)(\d+)', ref)
    col = 0
    for ch in m.group(1):
        col = col * 26 + (ord(ch) - 64)
    row = int(m.group(2))
    t = c.get('t')
    v = c.find(TAG + 'v')
    val = None
    if v is not None:
        if t == 's':
            val = shared[int(v.text)]
        elif t == 'inlineStr':
            is_elem = c.find(TAG + 'is')
            val = ''.join(x.text or '' for x in is_elem.iter(TAG + 't'))
        else:
            val = v.text
    elif t == 'inlineStr':
        is_elem = c.find(TAG + 'is')
        val = ''.join(x.text or '' for x in is_elem.iter(TAG + 't'))
    if val is not None:
        rows.setdefault(row, {})[col - 1] = val

def num(x):
    try:
        return float(x)
    except (TypeError, ValueError):
        return 0.0

cats = OrderedDict()
grand = 0.0
for r in range(11, 23):
    cat = rows.get(r, {}).get(0)
    item = rows.get(r, {}).get(1)
    amt = num(rows.get(r, {}).get(2))
    cats.setdefault(cat, []).append((item, amt))
    grand += amt

for cat, items in cats.items():
    subtotal = sum(a for _, a in items)
    print(f"{cat}: {subtotal:,.2f}  ({', '.join(f'{i}: {a:,.0f}' for i, a in items)})")
print(f"TOTAL EXPENSES: {grand:,.2f}")

income = sum(num(rows.get(r, {}).get(1)) for r in range(4, 8))
print(f"Total Income: {income:,.2f}")

